import { calculateInvoice } from '@fodt/invoice-maker';

const result = await calculateInvoice({
  number: '2026-001',
  issueDate: '2026-10-01',
  seller: 'Example Studio',
  buyer: 'Example Client',
  items: 'Widget | 2 | 19.99\nSetup | 1 | 5.00',
  discount: '10',
  taxRate: '20',
});
result?.totals.total; // '48.58'
result?.fileName; // 'invoice-2026-001.pdf'
result?.bytes; // the PDF file as a Uint8Array
